"""Main reconstruction: saved frame boundaries, action labels and credit indices."""
from common import *
KINDS=('fresh_target','initial_historical','session_repeat','non_target')
STATE_KEYS=('H','U','D','current','previous','E')
def credit_stage(c,b1,b2):
    t=c['tick'];return (0 if t<=b1 else 1 if t<=b2 else 2) if c['source']=='arrival' else (0 if t<b1 else 1 if t<b2 else 2)
def action_stats(actions):
    moves=[a for a in actions if a['kind']=='move'];counts={k:sum(a['classification']==k for a in moves) for k in KINDS}
    return dict(moves=len(moves),waits=sum(a['kind']=='wait' for a in actions),move_classes=counts,turns90=sum(a['turn_degrees']==90 for a in moves),turns180=sum(a['turn_degrees']==180 for a in moves))
def raw_context(sid,request):
    slot=next(r for r in read(S/'call_slots.json') if r['session']==sid and r['tick']==request['tick']);rid=slot['id'];out=read(S/'outputs'/(rid+'.json'));assert out['entry']['response']==request['response'] and (S/out['job']['input']).read_bytes().decode('utf8')==request['payload_utf8']
    return rid,out
def move_pointer(sid,s,action_index):
    a=s['actions'][action_index];reqidx=max(i for i,r in enumerate(s['requests']) if r['tick']<=a['tick']);req=s['requests'][reqidx];rid,out=raw_context(sid,req);prefix=[x for x in s['actions'][:action_index] if x['kind']=='move' and x['tick']>=req['tick']];i=len(prefix);route=req['response']['route'];assert route[i]==a['start'] and route[i+1]==a['end'];raw=out['entry']['native_return']['raw'];trace=raw.get('trace',[]);ti=max((j for j,e in enumerate(trace) if e.get('index',10**9)<=i),default=None)
    return dict(action=dict(file=str(S/'sessions'/(sid+'.json')),json_pointer='/sessions/'+out['job']['method']+'/actions/'+str(action_index)),response_output=str(S/'outputs'/(rid+'.json')),route_segment_indices=[i,i+1],native_trace_index=ti,native_trace_event=trace[ti] if ti is not None else None,P2_selected_output_source=raw.get('source'),P2_note='source/stage evidence only; no per-move candidate causal trace' if out['job']['method']=='P2_MULTI' else None)
def session_analysis(sj):
    sid=sj['id'];result=read(S/'sessions'/(sid+'.json'));s=result['sessions'][sj['method']];w=result['world'];b1,b2=[e['tick'] for e in w['events']];end=s['summary']['finish_tick'];segments=[]
    for i,(lo,hi) in enumerate(((0,b1),(b1,b2),(b2,end))):
        ids=[j for j,a in enumerate(s['actions']) if lo<=a['tick']<hi];stats=action_stats([s['actions'][j] for j in ids]);credits=[dict(credit_index=j,credit=c) for j,c in enumerate(s['credits']) if credit_stage(c,b1,b2)==i];state=s['frames'][hi-1]['after'] if i<2 else s['terminal']['state'];assert s['frames'][hi-1]['tick']==hi-1
        segments.append(dict(index=i,depart_tick_range=[lo,hi],right_boundary='before publication; arrival credit at hi belongs here' if i<2 else 'terminal state after final publication',**stats,first_credits=credits,first_credit_count=len(credits),zero_move_credit_count=sum(c['credit']['source']=='publication' for c in credits),end_state={k:state[k] for k in STATE_KEYS},source_action_indices=ids,end_frame_pointer=f'/sessions/{sj["method"]}/frames/{hi-1}/after' if i<2 else f'/sessions/{sj["method"]}/terminal/state'))
    assert sum(x['moves'] for x in segments)==s['summary']['M'] and sum(x['first_credit_count'] for x in segments)==len(s['credits'])
    for k in KINDS:assert sum(x['move_classes'][k] for x in segments)==s['summary']['move_classes'][k]
    req=s['requests'][-1];rid,out=raw_context(sid,req);c=req['input'];pending=ps(c['targets'])-ps(c['covered']);by_point={tuple(e['point']):(i,e) for i,e in enumerate(s['credits'])};ct=max((by_point[p][1]['tick'] for p in pending),default=b2);lastcredits=[dict(index=i,credit=e) for i,e in enumerate(s['credits']) if e['tick']==ct and tuple(e['point']) in pending];completion_point=lastcredits[-1]['credit']['point'] if lastcredits else c['current'];before=action_stats([a for a in s['actions'] if b2<=a['tick']<ct]);tail=action_stats([a for a in s['actions'] if ct<=a['tick']<end]);executed=[c['current']]+[a['end'] for a in s['actions'] if a['kind']=='move' and a['tick']>=b2];assert executed==req['response']['route'];assert before['moves']+tail['moves']==segments[2]['moves']
    final=dict(event_tick=b2,response_id=rid,remaining_at_publication=ls(pending),completion_tick=ct,completion_position=completion_point,last_completion_credits=lastcredits,no_remaining_at_publication=not pending,to_completion=before,after_completion_to_base=tail,terminal_tick=end,complete_response_steps=len(req['response']['route'])-1,actual_executed_response_steps=len(executed)-1,response_fully_executed=True,unexecuted_steps=0,final_actual_position=s['summary']['current'],response_output=str(S/'outputs'/(rid+'.json')),request_pointer=f'/sessions/{sj["method"]}/requests/2',waits_after_last_event=before['waits']+tail['waits'])
    # Every contiguous run is retained, not a selected alleged shortcut.
    runs=[];current=None
    for j,a in enumerate(s['actions']):
        kind=a.get('classification') if a['kind']=='move' else None
        if kind in ('session_repeat','initial_historical','non_target'):
            if current and current['classification']==kind and current['action_indices'][-1]+1==j:current['action_indices'].append(j);current['path'].append(a['end']);current['arrival_end_tick']=a['arrival_tick'];current['steps']+=1
            else:
                current=dict(classification=kind,action_indices=[j],depart_start_tick=a['tick'],arrival_end_tick=a['arrival_tick'],steps=1,path=[a['start'],a['end']]);runs.append(current)
        else:current=None
    for r in runs:r['first_move_source']=move_pointer(sid,s,r['action_indices'][0])
    return dict(session=sj,segments=segments,final_completion=final,all_repeat_and_non_target_runs=runs,summary=s['summary'])
def main():
    violations=install_guard();require_sources();order=read(S/'session_order.json');assert len(order)==12;analyses=[session_analysis(s) for s in order];by={a['session']['id']:a for a in analyses};layers=[];costs=[];different_credit=[];detail={}
    for wid,w in read(S/'worlds.json').items():
        data={m:read(S/'sessions'/(wid+'_'+m+'.json'))['sessions'][m] for m in ('PPCPP','P2_MULTI')};reqs={m:s['requests'][-1] for m,s in data.items()};cs={m:r['input'] for m,r in reqs.items()};outs={m:raw_context(wid+'_'+m,reqs[m])[1] for m in data}
        physical={m:dict(F=cs[m]['free'],P=cs[m]['published_targets'],H=cs[m]['covered'],U=ls(ps(cs[m]['targets'])-ps(cs[m]['covered'])),D=cs[m]['deferred_targets'],current=cs[m]['current'],previous=cs[m]['previous'],base=cs[m]['base'],E=cs[m]['distance_budget'],zero_move_credits_before_or_at_last=[e for e in data[m]['credits'] if e['source']=='publication' and e['tick']<=w['events'][-1]['tick']]) for m in data};setfields={'F','P','H','U','D'};equal={k:(ps(physical['PPCPP'][k])==ps(physical['P2_MULTI'][k]) if k in setfields else physical['PPCPP'][k]==physical['P2_MULTI'][k]) for k in physical['PPCPP']};interface={m:dict(initial_targets=cs[m]['initial_targets'],old_route=cs[m]['old_route'],predator=cs[m]['predator'],entry_budget=outs[m]['entry']['entry_budget'],forwarded_inner_budget=outs[m]['entry']['inner_budget'],preprocess_seconds=outs[m]['entry']['preprocess_seconds'],seed=outs[m]['job']['seed'],radius=cs[m]['radius']) for m in data};ieq={k:interface['PPCPP'][k]==interface['P2_MULTI'][k] for k in interface['PPCPP']};a,b=[by[wid+'_'+m] for m in ('PPCPP','P2_MULTI')];same_final=ps(a['summary']['H'])==ps(b['summary']['H']) and ps(a['summary']['D'])==ps(b['summary']['D']);dm=a['summary']['M']-b['summary']['M'];segment_delta=[x['moves']-y['moves'] for x,y in zip(a['segments'],b['segments'])];class_delta={k:a['summary']['move_classes'][k]-b['summary']['move_classes'][k] for k in KINDS};to_delta=a['final_completion']['to_completion']['moves']-b['final_completion']['to_completion']['moves'];tail_delta=a['final_completion']['after_completion_to_base']['moves']-b['final_completion']['after_completion_to_base']['moves'];assert sum(segment_delta)==sum(class_delta.values())==dm and to_delta+tail_delta==segment_delta[2]
        layers.append(dict(world=wid,physical_states=physical,physical_field_equal=equal,all_physical_fields_equal=all(equal.values()),interface_states=interface,interface_field_equal=ieq,complete_interface_equal=all(ieq.values()),result=dict(last_routes_identical=reqs['PPCPP']['response']['route']==reqs['P2_MULTI']['response']['route'],complete_response_steps={m:len(reqs[m]['response']['route'])-1 for m in data},response_fully_executed_both=True,waits_after_last={m:by[wid+'_'+m]['final_completion']['waits_after_last_event'] for m in data})))
        costs.append(dict(world=wid,same_final_H_D=same_final,delta_M=dm,three_segment_delta_M=segment_delta,all_four_class_delta=class_delta,last_event_to_completion_delta=to_delta,after_completion_return_delta=tail_delta,last_response_length_delta=(len(reqs['PPCPP']['response']['route'])-len(reqs['P2_MULTI']['response']['route'])),final_completion_positions={m:by[wid+'_'+m]['final_completion']['completion_position'] for m in data},no_wait_before_fixed_events=all(a0['segments'][0]['waits']==a0['segments'][1]['waits']==0 for a0 in (a,b)),note='Independent conserved partitions; do not add class differences to phase differences as extra costs'))
        if wid=='I_M':
            s,t=[data[m] for m in ('PPCPP','P2_MULTI')];j=next(i for i,(x,y) in enumerate(zip(s['actions'],t['actions'])) if (x['start'],x['end'])!=(y['start'],y['end']));detail=dict(first_different_actions={m:dict(action=data[m]['actions'][j],source=move_pointer(wid+'_'+m,data[m],j)) for m in data},last_event_physical_state_differences={k:dict(PPCPP_only=ls(ps(physical['PPCPP'][k])-ps(physical['P2_MULTI'][k])),P2_only=ls(ps(physical['P2_MULTI'][k])-ps(physical['PPCPP'][k]))) for k in ('H','U')},current_and_previous={m:dict(current=cs[m]['current'],previous=cs[m]['previous']) for m in data},first_credits_before_event2={m:[dict(index=i,credit=e) for i,e in enumerate(data[m]['credits']) if e['tick']<=w['events'][-1]['tick']] for m in data},no_counterfactual_cost_identified=True)
